using EduManageLms.Api.Common; using EduManageLms.Api.Domain; using EduManageLms.Api.Infrastructure; using MongoDB.Driver;
namespace EduManageLms.Api.Application;
public sealed class AuthService(MongoContext db,JwtTokenService jwt):IAuthService{public async Task<LoginResponse> LoginAsync(LoginRequest r,string ip,string ua,CancellationToken ct){var id=r.Identifier.Trim().ToLowerInvariant();var user=await db.Users.Find(x=>!x.IsDeleted&&(x.Email==id||x.Username==id)).FirstOrDefaultAsync(ct);if(user is null){await Log(id,null,false,"Tài khoản không tồn tại",ip,ua,ct);throw new AppException("Tên đăng nhập hoặc mật khẩu không đúng",401);}if(user.LockedUntil>DateTime.UtcNow||user.Status=="Locked")throw new AppException("Tài khoản đang bị khóa",423);if(user.Status!="Active")throw new ForbiddenException("Tài khoản đã ngừng hoạt động");if(!BCrypt.Net.BCrypt.Verify(r.Password,user.PasswordHash)){user.FailedLoginCount++;if(user.FailedLoginCount>=5){user.LockedUntil=DateTime.UtcNow.AddMinutes(15);user.Status="Locked";}await db.Users.ReplaceOneAsync(x=>x.Id==user.Id,user,cancellationToken:ct);await Log(id,user.Id,false,"Mật khẩu sai",ip,ua,ct);throw new AppException("Tên đăng nhập hoặc mật khẩu không đúng",401);}user.FailedLoginCount=0;user.LockedUntil=null;user.LastLoginAt=DateTime.UtcNow;var access=jwt.Create(user);var refresh=jwt.NewRefreshToken();user.RefreshTokens.RemoveAll(x=>!x.IsActive);user.RefreshTokens.Add(new(){TokenHash=jwt.Hash(refresh),ExpiresAt=jwt.RefreshExpiry(),Device=ua});await db.Users.ReplaceOneAsync(x=>x.Id==user.Id,user,cancellationToken:ct);await Log(id,user.Id,true,null,ip,ua,ct);return new(access.token,refresh,access.expires,new(user.Id,user.Username,user.Email,user.FullName,user.Role,user.AvatarUrl));}
 public async Task<LoginResponse> RefreshAsync(string token,string userAgent,CancellationToken ct){var hash=jwt.Hash(token);var user=await db.Users.Find(x=>x.RefreshTokens.Any(t=>t.TokenHash==hash)).FirstOrDefaultAsync(ct)??throw new AppException("Refresh token không hợp lệ",401);var old=user.RefreshTokens.First(x=>x.TokenHash==hash);if(!old.IsActive)throw new AppException("Refresh token đã hết hạn hoặc bị thu hồi",401);old.RevokedAt=DateTime.UtcNow;var next=jwt.NewRefreshToken();user.RefreshTokens.Add(new(){TokenHash=jwt.Hash(next),ExpiresAt=jwt.RefreshExpiry(),Device=userAgent});var access=jwt.Create(user);await db.Users.ReplaceOneAsync(x=>x.Id==user.Id,user,cancellationToken:ct);return new(access.token,next,access.expires,new(user.Id,user.Username,user.Email,user.FullName,user.Role,user.AvatarUrl));}
 public async Task RevokeAllAsync(string userId,CancellationToken ct){var user=await db.Users.Find(x=>x.Id==userId).FirstOrDefaultAsync(ct)??throw new NotFoundException();foreach(var t in user.RefreshTokens.Where(x=>x.IsActive))t.RevokedAt=DateTime.UtcNow;await db.Users.ReplaceOneAsync(x=>x.Id==user.Id,user,cancellationToken:ct);}
 public async Task ChangePasswordAsync(string userId,string currentPassword,string newPassword,CancellationToken ct){if(newPassword.Length<8)throw new AppException("Mật khẩu mới phải có ít nhất 8 ký tự");var user=await db.Users.Find(x=>x.Id==userId).FirstOrDefaultAsync(ct)??throw new NotFoundException();if(!BCrypt.Net.BCrypt.Verify(currentPassword,user.PasswordHash))throw new AppException("Mật khẩu hiện tại không đúng");if(BCrypt.Net.BCrypt.Verify(newPassword,user.PasswordHash))throw new AppException("Không được dùng lại mật khẩu hiện tại");user.PasswordHash=BCrypt.Net.BCrypt.HashPassword(newPassword);foreach(var t in user.RefreshTokens.Where(x=>x.IsActive))t.RevokedAt=DateTime.UtcNow;user.UpdatedAt=DateTime.UtcNow;await db.Users.ReplaceOneAsync(x=>x.Id==user.Id,user,cancellationToken:ct);}
 public async Task RevokeAsync(string token,CancellationToken ct){var hash=jwt.Hash(token);var user=await db.Users.Find(x=>x.RefreshTokens.Any(t=>t.TokenHash==hash)).FirstOrDefaultAsync(ct);if(user is null)return;var t=user.RefreshTokens.First(x=>x.TokenHash==hash);t.RevokedAt=DateTime.UtcNow;await db.Users.ReplaceOneAsync(x=>x.Id==user.Id,user,cancellationToken:ct);}private Task Log(string identifier,string? uid,bool ok,string? reason,string ip,string ua,CancellationToken ct)=>db.LoginHistories.InsertOneAsync(new(){Identifier=identifier,UserId=uid,Success=ok,FailureReason=reason,IpAddress=ip,UserAgent=ua},cancellationToken:ct);}
